def add_without_plus(a, b):
    MASK = 0xFFFFFFFF
    a &= MASK
    b &= MASK
    while b:
        a, b = (a ^ b) & MASK, ((a & b) << 1) & MASK
    if a >= 0x80000000:
        a = ~(a ^ MASK)
    return a
